'use client';
import { useCallback, useEffect, useRef, useState, type MouseEvent, type PointerEvent } from 'react';
import { duration as D, useStudioMotion } from '../../motion';
import { StudioCanvas } from '../../three';
import type { EffectProps } from '../../types';
import { POSTERS, posterCanvas, posterFonts, readTheme, type Theme } from './posters';
import { Scene, type Pointer } from './scene';
import styles from './styles.module.css';

type Params = { amplitude: number; chroma: number; duration: number; frequency: number; hover: boolean };

function useThemeVersion(): number {
  const [v, setV] = useState(0);
  useEffect(() => {
    const bump = () => setV((n) => n + 1);
    const mo = new MutationObserver(bump);
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme', 'class', 'style'] });
    const mq = window.matchMedia?.('(prefers-color-scheme: dark)');
    mq?.addEventListener('change', bump);
    return () => { mo.disconnect(); mq?.removeEventListener('change', bump); };
  }, []);
  return v;
}

/** No-WebGL fallback: the same posters drawn with canvas2d, cross-faded with CSS. */
function PosterImages({ index, theme, version }: { index: number; theme: Theme | null; version: number }) {
  const [srcs, setSrcs] = useState<string[]>([]);
  useEffect(() => { if (theme) setSrcs(POSTERS.map((_, i) => posterCanvas(i, 600, theme).toDataURL('image/png'))); }, [theme, version]);
  return (
    <div className={styles.stack}>
      {srcs.map((src, i) => (
        // eslint-disable-next-line @next/next/no-img-element
        <img key={i} src={src} alt="" className={styles.still} data-on={i === index || undefined} />
      ))}
    </div>
  );
}

export default function ImageRippleDistortion({ params }: EffectProps<Params>) {
  const { reduced } = useStudioMotion();
  const root = useRef<HTMLDivElement>(null);
  const pointer = useRef<Pointer>({ x: 0.5, y: 0.5, inside: false });
  const kick = useRef<(() => void) | null>(null);
  const [index, setIndex] = useState(0);
  const [origin, setOrigin] = useState<[number, number]>([0.5, 0.5]);
  const [theme, setTheme] = useState<Theme | null>(null);
  const [fonts, setFonts] = useState(0);
  const themeVersion = useThemeVersion();

  // Theme colours + fonts from the tokens; redraw once the faces have actually loaded.
  useEffect(() => {
    if (!root.current) return;
    const t = readTheme(root.current);
    setTheme(t);
    let alive = true;
    if (document.fonts?.load) Promise.all(posterFonts(t).map((f) => document.fonts.load(f).catch(() => []))).then(() => { if (alive) setFonts((n) => n + 1); });
    return () => { alive = false; };
  }, [themeVersion]);

  const next = useCallback((at: [number, number] = [0.5, 0.5]) => {
    setOrigin(at);
    setIndex((i) => (i + 1) % POSTERS.length);
  }, []);

  const uv = (e: MouseEvent<HTMLDivElement>): [number, number] => {
    const r = e.currentTarget.getBoundingClientRect();
    return [(e.clientX - r.left) / r.width, 1 - (e.clientY - r.top) / r.height];
  };
  const onMove = (e: PointerEvent<HTMLDivElement>) => {
    const [x, y] = uv(e);
    pointer.current = { x, y, inside: e.pointerType === 'mouse' };
    kick.current?.();
  };
  const onLeave = () => { pointer.current = { ...pointer.current, inside: false }; kick.current?.(); };

  const poster = POSTERS[index];
  return (
    <div ref={root} className={styles.root}>
      <div className={styles.frame} onPointerMove={onMove} onPointerLeave={onLeave} onClick={(e) => next(uv(e))}>
        <StudioCanvas
          label={`Poster ${index + 1} of ${POSTERS.length}: ${poster.title}`}
          description="A generated typographic poster. Choosing Next sends a ripple across it that bends and splits the colour channels as the next poster is revealed."
          fallback={<PosterImages index={index} theme={theme} version={themeVersion + fonts * 100} />}
        >
          <Scene
            index={index}
            origin={origin}
            theme={theme}
            version={themeVersion + fonts * 100}
            duration={reduced ? D.fast : params.duration}
            amp={params.amplitude}
            chroma={params.chroma}
            freq={params.frequency}
            hover={params.hover}
            fade={reduced}
            pointer={pointer}
            kick={kick}
          />
        </StudioCanvas>
      </div>
      <div className={styles.panel}>
        <p className={styles.kicker}>Poster {String(index + 1).padStart(2, '0')} / {String(POSTERS.length).padStart(2, '0')} · sample series</p>
        <div aria-live="polite" className={styles.caption}>
          <p className={styles.title}>{poster.title}</p>
          <p className={styles.sub}>{poster.subtitle}</p>
        </div>
        <button type="button" className={styles.next} onClick={() => next()}>
          Next poster
          <svg viewBox="0 0 16 16" aria-hidden="true" focusable="false"><path d="M3 8h10M9 4l4 4-4 4" /></svg>
        </button>
        <p className={styles.hint}>
          {reduced ? 'Reduced motion: posters cross-fade without distortion.' : `Click the poster to ripple from that point${params.hover ? '; hovering stirs the surface' : ''}.`}
        </p>
      </div>
    </div>
  );
}

/**
 * Three generated posters for a fictional exhibition series, drawn with canvas2d in the CURRENT theme colours
 * (read from the --s3-* tokens on the element), so the textures follow light and dark themes.
 */
export interface Poster { title: string; subtitle: string }
export const POSTERS: readonly Poster[] = [
  { title: 'Tidewater', subtitle: 'Studies in slow motion · No. 01' },
  { title: 'Meridian', subtitle: 'Studies in slow motion · No. 02' },
  { title: 'Field Notes', subtitle: 'Studies in slow motion · No. 03' },
];

export interface Theme { paper: string; ink: string; signal: string; muted: string; display: string; serif: string; mono: string }

export function readTheme(el: Element): Theme {
  const cs = getComputedStyle(el);
  const v = (name: string, fallback: string) => cs.getPropertyValue(name).trim() || fallback;
  return {
    paper: v('--s3-surface', '#fbf9f4'), ink: v('--s3-ink', '#11110f'), signal: v('--s3-signal', '#bf2f09'), muted: v('--s3-ink-muted', '#5c5a52'),
    display: v('--s3-font-display', 'system-ui, sans-serif'), serif: v('--s3-font-serif', 'Georgia, serif'), mono: v('--s3-font-mono', 'ui-monospace, monospace'),
  };
}

/** Fonts the posters use; resolve before (re)drawing so the canvas never caches a fallback face. */
export const posterFonts = (t: Theme) => [`700 100px ${t.display}`, `italic 400 100px ${t.serif}`, `500 20px ${t.mono}`];

function setFont(g: CanvasRenderingContext2D, font: string, fallback: string) {
  g.font = fallback;
  g.font = font; // ignored by the canvas if the family list does not parse — the fallback stays
}

export function drawPoster(g: CanvasRenderingContext2D, i: number, w: number, h: number, t: Theme): void {
  const u = w / 600; // design unit: the posters are composed on a 600 × 800 grid
  const label = (text: string, x: number, y: number, color: string, align: CanvasTextAlign = 'left') => {
    setFont(g, `500 ${14 * u}px ${t.mono}`, `500 ${14 * u}px monospace`);
    g.fillStyle = color; g.textAlign = align; g.fillText(text.toUpperCase(), x, y);
  };
  g.save();
  if (i === 0) {
    g.fillStyle = t.paper; g.fillRect(0, 0, w, h);
    g.fillStyle = t.signal; g.beginPath(); g.arc(410 * u, 250 * u, 150 * u, 0, Math.PI * 2); g.fill();
    g.fillStyle = t.ink;
    for (let k = 0; k < 11; k++) { const y = (430 + k * 26) * u; g.fillRect(0, y, w, Math.max(1, (14 - k * 1.1) * u)); }
    setFont(g, `700 ${100 * u}px ${t.display}`, `700 ${100 * u}px sans-serif`);
    g.fillStyle = t.ink; g.textAlign = 'left'; g.fillText('Tidewater', 34 * u, 760 * u, 532 * u);
    label(POSTERS[0].subtitle, 36 * u, 56 * u, t.ink);
    label('Sample poster', 564 * u, 56 * u, t.ink, 'right');
  } else if (i === 1) {
    g.fillStyle = t.ink; g.fillRect(0, 0, w, h);
    g.strokeStyle = t.paper; g.globalAlpha = 0.22; g.lineWidth = Math.max(1, u);
    for (let x = 60; x < 600; x += 60) { g.beginPath(); g.moveTo(x * u, 0); g.lineTo(x * u, h); g.stroke(); }
    for (let y = 80; y < 800; y += 80) { g.beginPath(); g.moveTo(0, y * u); g.lineTo(w, y * u); g.stroke(); }
    g.globalAlpha = 1;
    g.fillStyle = t.signal; g.fillRect(300 * u, 0, 60 * u, h);
    g.fillStyle = t.paper; g.beginPath(); g.arc(330 * u, 330 * u, 92 * u, 0, Math.PI * 2); g.fill();
    setFont(g, `italic 400 ${150 * u}px ${t.serif}`, `italic 400 ${150 * u}px serif`);
    g.fillStyle = t.paper; g.textAlign = 'center'; g.fillText('Meridian', 300 * u, 640 * u, 540 * u);
    label(POSTERS[1].subtitle, 300 * u, 720 * u, t.paper, 'center');
    label('Sample poster', 300 * u, 56 * u, t.paper, 'center');
  } else {
    g.fillStyle = t.signal; g.fillRect(0, 0, w, h);
    for (let k = 7; k >= 1; k--) {
      g.fillStyle = k % 2 ? t.ink : t.paper;
      g.beginPath(); g.moveTo(0, h); g.arc(0, h, k * 78 * u, -Math.PI / 2, 0); g.closePath(); g.fill();
    }
    setFont(g, `700 ${104 * u}px ${t.display}`, `700 ${104 * u}px sans-serif`);
    g.fillStyle = t.paper; g.textAlign = 'right'; g.fillText('Field', 566 * u, 150 * u, 400 * u); g.fillText('Notes', 566 * u, 250 * u, 400 * u);
    label(POSTERS[2].subtitle, 566 * u, 300 * u, t.paper, 'right');
    label('Sample poster', 36 * u, 56 * u, t.paper);
  }
  g.restore();
}

/** Draw poster `i` into a fresh canvas element (used for textures and for the no-WebGL fallback images). */
export function posterCanvas(i: number, w: number, t: Theme): HTMLCanvasElement {
  const c = document.createElement('canvas');
  c.width = Math.round(w); c.height = Math.round((w * 4) / 3);
  const g = c.getContext('2d');
  if (g) drawPoster(g, i, c.width, c.height, t);
  return c;
}

'use client';
import { useFrame, useThree } from '@react-three/fiber';
import { useEffect, useMemo, useRef, type RefObject } from 'react';
import { CanvasTexture, LinearFilter, ShaderMaterial, SRGBColorSpace, Vector2 } from 'three';
import { useQuality } from '../../three';
import { POSTERS, posterCanvas, type Theme } from './posters';
import { fragmentShader, vertexShader } from './shader';

export interface Pointer { x: number; y: number; inside: boolean }
export interface SceneProps {
  index: number;
  origin: [number, number];
  theme: Theme | null;
  version: number;
  duration: number;
  amp: number;
  chroma: number;
  freq: number;
  hover: boolean;
  fade: boolean;
  pointer: RefObject<Pointer>;
  kick: RefObject<(() => void) | null>;
}

const ease = (t: number) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);

export function Scene({ index, origin, theme, version, duration, amp, chroma, freq, hover, fade, pointer, kick }: SceneProps) {
  const invalidate = useThree((s) => s.invalidate);
  const { textureMax } = useQuality();
  const anim = useRef({ t: 1, from: index, to: index, hover: 0, time: 0 });

  // Poster textures in the current theme: regenerated on theme/font changes, the old set disposed.
  const textures = useMemo(() => {
    if (!theme) return null;
    const width = Math.min(textureMax, 1024) * 0.75;
    return POSTERS.map((_, i) => {
      const tex = new CanvasTexture(posterCanvas(i, width, theme));
      tex.colorSpace = SRGBColorSpace;
      tex.minFilter = LinearFilter; // no mipmaps needed: the poster is shown at about its own size
      tex.generateMipmaps = false;
      return tex;
    });
  }, [theme, version, textureMax]);
  useEffect(() => () => { for (const t of textures ?? []) t.dispose(); }, [textures]);

  const uniforms = useMemo(() => ({
    uFrom: { value: null as CanvasTexture | null }, uTo: { value: null as CanvasTexture | null },
    uProgress: { value: 0 }, uAmp: { value: 0.05 }, uChroma: { value: 1 }, uFreq: { value: 3 }, uTime: { value: 0 },
    uHover: { value: 0 }, uAspect: { value: 0.75 }, uFade: { value: 0 }, uOrigin: { value: new Vector2(0.5, 0.5) }, uPointer: { value: new Vector2(0.5, 0.5) },
  }), []);

  // Built imperatively on purpose: R3F copies each uniform object when `uniforms` is passed as a JSX prop, so writes
  // to `.value` on our object would never reach the material.
  const material = useMemo(() => new ShaderMaterial({ uniforms, vertexShader, fragmentShader, depthTest: false, depthWrite: false }), [uniforms]);
  useEffect(() => () => material.dispose(), [material]);

  useEffect(() => { kick.current = invalidate; return () => { kick.current = null; }; }, [kick, invalidate]);
  useEffect(() => {
    uniforms.uAmp.value = amp; uniforms.uChroma.value = chroma; uniforms.uFreq.value = freq; uniforms.uFade.value = fade ? 1 : 0;
    invalidate();
  }, [amp, chroma, freq, fade, uniforms, invalidate]);

  // A new index starts a transition from whatever is on screen (an unfinished one is completed first).
  useEffect(() => {
    const a = anim.current;
    if (index === a.to) return;
    a.from = a.to; a.to = index; a.t = 0;
    uniforms.uOrigin.value.set(origin[0], origin[1]);
    invalidate();
  }, [index, origin, uniforms, invalidate]);

  useEffect(() => {
    if (!textures) return;
    const a = anim.current;
    uniforms.uFrom.value = textures[a.t < 1 ? a.from : a.to];
    uniforms.uTo.value = textures[a.to];
    invalidate();
  }, [textures, uniforms, invalidate]);

  useFrame((_, rawDt) => {
    if (!textures) return;
    const a = anim.current;
    const dt = Math.min(rawDt, 1 / 20);
    let busy = false;
    if (a.t < 1) {
      a.t = Math.min(1, a.t + (dt * 1000) / Math.max(60, duration));
      uniforms.uFrom.value = textures[a.from];
      uniforms.uTo.value = textures[a.to];
      uniforms.uProgress.value = ease(a.t);
      if (a.t >= 1) { uniforms.uFrom.value = textures[a.to]; uniforms.uProgress.value = 0; } else busy = true;
    }
    const p = pointer.current;
    const goal = hover && !fade && p?.inside ? 1 : 0;
    if (p) uniforms.uPointer.value.lerp(new Vector2(p.x, p.y), 1 - Math.exp(-dt * 10));
    a.hover += (goal - a.hover) * (1 - Math.exp(-dt * 5));
    if (Math.abs(goal - a.hover) < 0.002) a.hover = goal;
    uniforms.uHover.value = a.hover;
    if (a.hover > 0) { a.time += dt; uniforms.uTime.value = a.time; busy = true; }
    if (busy) invalidate();
  });

  return (
    <mesh frustumCulled={false} material={material}>
      <planeGeometry args={[2, 2]} />
    </mesh>
  );
}

/** Full-frame poster transition: a ripple front travels out from the origin, displacing and splitting colour. */
export const vertexShader = /* glsl */ `
varying vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = vec4(position.xy, 0.0, 1.0); // clip-space quad; the canvas itself has the poster's aspect ratio
}`;

export const fragmentShader = /* glsl */ `
precision highp float;
varying vec2 vUv;
uniform sampler2D uFrom, uTo;
uniform float uProgress, uAmp, uChroma, uFreq, uTime, uHover, uAspect, uFade;
uniform vec2 uOrigin, uPointer;

vec3 sampleSplit(sampler2D tex, vec2 uv, vec2 split) {
  return vec3(texture2D(tex, uv + split).r, texture2D(tex, uv).g, texture2D(tex, uv - split).b);
}

void main() {
  vec2 uv = vUv;
  vec2 d = (uv - uOrigin) * vec2(uAspect, 1.0);
  float dist = length(d);
  vec2 dir = dist > 1e-4 ? d / dist : vec2(0.0);
  float front = uProgress * 1.75;                                  // reaches the far corner at progress 1
  float band = exp(-pow((dist - front) * 4.5, 2.0));               // energy concentrated around the front
  float wave = sin((dist - front) * uFreq * 6.2831853) * band;
  float env = sin(uProgress * 3.1415927);                          // calm at rest, strongest mid-transition
  vec2 offset = dir * wave * uAmp * env * (1.0 - uFade);

  // Subtle hover ripple around the pointer (fades with uHover).
  vec2 hp = (uv - uPointer) * vec2(uAspect, 1.0);
  float hd = length(hp);
  vec2 hdir = hd > 1e-4 ? hp / hd : vec2(0.0);
  offset += hdir * sin(hd * 70.0 - uTime * 5.0) * exp(-hd * 9.0) * 0.0045 * uHover * (1.0 - uFade);

  vec2 split = offset * uChroma * 0.9;
  vec3 a = sampleSplit(uFrom, uv + offset, split);
  vec3 b = sampleSplit(uTo, uv + offset * 0.6, split);
  // Inside the front the new poster shows; reduced motion (uFade = 1) is a plain cross-fade.
  float reveal = mix(1.0 - smoothstep(front - 0.08, front + 0.02, dist), uProgress, uFade);
  gl_FragColor = vec4(mix(a, b, reveal), 1.0);
  #include <colorspace_fragment>
}`;

.root {
  container-type: inline-size;
  width: 100%;
  align-self: stretch;
  display: grid;
  grid-template-columns: auto minmax(0, 20rem);
  align-items: center;
  justify-content: center;
  gap: clamp(24px, 6cqi, 64px);
  padding: clamp(20px, 5cqi, 48px) clamp(16px, 4cqi, 40px);
  font-family: var(--s3-font-text, ui-sans-serif, system-ui, sans-serif);
  color: var(--s3-ink, #11110f);
}
.frame {
  position: relative;
  height: clamp(340px, 62cqi, 480px);
  aspect-ratio: 3 / 4;
  max-width: 100%;
  overflow: hidden;
  border-radius: var(--s3-radius-s, 4px);
  box-shadow: 0 1px 0 var(--s3-line, #11110f24), 0 18px 40px -18px rgb(0 0 0 / 0.45);
  cursor: pointer;
}
.frame > [data-studio3-canvas] { position: absolute !important; inset: 0; min-height: 0 !important; }
.stack { position: absolute; inset: 0; }
.still { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; opacity: 0; transition: opacity var(--s3-duration-slow, 560ms) var(--s3-ease-standard, ease); }
.still[data-on] { opacity: 1; }

.panel { display: grid; gap: 14px; justify-items: start; }
.kicker {
  margin: 0;
  font-family: var(--s3-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-variant-numeric: tabular-nums;
  color: var(--s3-ink-muted, #5c5a52);
}
.caption { display: grid; gap: 6px; }
.title {
  margin: 0;
  font-family: var(--s3-font-display, ui-sans-serif, system-ui, sans-serif);
  font-size: clamp(2rem, 6cqi, 3rem);
  font-weight: 700;
  line-height: 0.95;
  letter-spacing: -0.035em;
}
.sub { margin: 0; font-size: 0.9375rem; color: var(--s3-ink-muted, #5c5a52); }
.next {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-height: 44px;
  padding: 0 18px 0 20px;
  border: 1px solid var(--s3-line-strong, #11110f);
  border-radius: 999px;
  background: var(--s3-ink, #11110f);
  color: var(--s3-surface, #fbf9f4);
  font: inherit;
  font-size: 0.875rem;
  font-weight: 600;
  cursor: pointer;
}
.next svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
.next:focus-visible { outline: 2px solid var(--s3-focus, #1d4ed8); outline-offset: 3px; }
.hint { margin: 0; max-width: 30ch; font-size: 0.8125rem; line-height: 1.45; color: var(--s3-ink-muted, #5c5a52); }

@container (max-width: 620px) {
  .root { grid-template-columns: minmax(0, 1fr); justify-items: center; }
  .frame { height: auto; width: min(100%, 340px); }
  .panel { justify-items: center; text-align: center; }
}
@media (prefers-reduced-motion: reduce) {
  .still { transition-duration: var(--s3-duration-fast, 160ms); }
}
